export class MemberSuspendedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly memberId: string) {
    super(`Member ${memberId} is suspended and cannot take new work`);
    this.name = "MemberSuspendedError";
  }
}

/**
 * Throws `MemberSuspendedError` when `userId` is suspended in `orgId`. Used by
 * every write that would hand new work to a member.
 */
export async function assertMemberNotSuspended(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member?.status === "suspended") {
    throw new MemberSuspendedError(member.id);
  }
}

/**
 * Suspension is reversible access control: the member keeps their row, role
 * and seat, and simply cannot act until reinstated. Owners are protected by
 * the same last-owner rule as a removal.
 */
export async function suspendMember(
  actor: Actor,
